content:
:root {
  --bg-primary: #f8fafc;
  --bg-card: #ffffff;
  --bg-card-hover: #f1f5f9;
  --text-main: #0f172a;
  --text-muted: #64748b;
  --text-light: #94a3b8;
  --border-color: #e2e8f0;
  --primary-color: #3b82f6;
  --primary-hover: #2563eb;
  --danger-color: #ef4444;
  --danger-hover: #dc2626;
  --radius-sm: 6px;
  --radius-md: 10px;
  --radius-lg: 16px;
  --shadow-sm: 0 1px 3px rgba(0, 0, 0, 0.05);
  --shadow-md: 0 4px 6px -1px rgba(0, 0, 0, 0.07), 0 2px 4px -2px rgba(0, 0, 0, 0.05);
  --shadow-lg: 0 10px 15px -3px rgba(0, 0, 0, 0.08), 0 4px 6px -4px rgba(0, 0, 0, 0.04);
}

* {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, "Helvetica Neue", Arial, "Noto Sans JP", sans-serif;
  background-color: var(--bg-primary);
  color: var(--text-main);
  line-height: 1.5;
  -webkit-font-smoothing: antialiased;
}

.app-container {
  max-width: 1200px;
  margin: 0 auto;
  padding: 24px 16px;
  min-height: 100vh;
  display: flex;
  flex-direction: column;
}

.header {
  text-align: center;
  margin-bottom: 28px;
}

.header-title {
  font-size: 1.75rem;
  font-weight: 700;
  color: var(--text-main);
  letter-spacing: -0.02em;
  margin-bottom: 6px;
}

.header-subtitle {
  font-size: 0.95rem;
  color: var(--text-muted);
}

.main-layout {
  display: grid;
  grid-template-columns: 1fr;
  gap: 24px;
}

@media (min-width: 900px) {
  .main-layout {
    grid-template-columns: 1.1fr 1fr;
    align-items: start;
  }
}

/* グラフセクション */
.chart-section {
  background-color: var(--bg-card);
  border-radius: var(--radius-lg);
  padding: 24px;
  box-shadow: var(--shadow-md);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 20px;
}

.chart-wrapper {
  position: relative;
  width: 100%;
  height: 320px;
  display: flex;
  align-items: center;
  justify-content: center;
}

.chart-center-label {
  font-size: 0.85rem;
  font-weight: 600;
  color: var(--text-muted);
  text-anchor: middle;
}

.chart-center-amount {
  font-size: 1.25rem;
  font-weight: 700;
  fill: var(--text-main);
  text-anchor: middle;
}

/* 選択項目のクローズアップカード */
.selected-info-card {
  background: linear-gradient(135deg, #f0fdf4 0%, #e0f2fe 100%);
  border: 1px solid #bae6fd;
  border-radius: var(--radius-md);
  padding: 16px 20px;
  display: flex;
  flex-direction: column;
  gap: 6px;
  transition: all 0.2s ease-in-out;
}

.selected-info-title {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--text-muted);
}

.selected-info-amount {
  font-size: 1.5rem;
  font-weight: 700;
  color: var(--text-main);
}

.selected-info-percent {
  font-size: 0.9rem;
  font-weight: 600;
  color: var(--primary-color);
}

.selected-info-placeholder {
  font-size: 0.875rem;
  color: var(--text-muted);
  text-align: center;
  padding: 12px 0;
}

/* リスト・入力セクション */
.list-section {
  display: flex;
  flex-direction: column;
  gap: 20px;
}

/* 合計金額カード */
.total-summary-card {
  background-color: var(--bg-card);
  border-radius: var(--radius-lg);
  padding: 20px 24px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border-color);
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.total-label {
  font-size: 1rem;
  font-weight: 600;
  color: var(--text-muted);
}

.total-value {
  font-size: 1.75rem;
  font-weight: 800;
  color: var(--text-main);
}

/* 支出項目リスト */
.item-list {
  display: flex;
  flex-direction: column;
  gap: 10px;
  max-height: 400px;
  overflow-y: auto;
  padding-right: 4px;
}

.item-list::-webkit-scrollbar {
  width: 6px;
}

.item-list::-webkit-scrollbar-track {
  background: transparent;
}

.item-list::-webkit-scrollbar-thumb {
  background-color: #cbd5e1;
  border-radius: 3px;
}

.item-card {
  background-color: var(--bg-card);
  border-radius: var(--radius-md);
  padding: 12px 16px;
  border: 1px solid var(--border-color);
  display: flex;
  align-items: center;
  gap: 12px;
  cursor: pointer;
  transition: all 0.2s ease;
  user-select: none;
}

.item-card:hover {
  background-color: var(--bg-card-hover);
  border-color: #cbd5e1;
  transform: translateY(-1px);
}

.item-card-selected {
  border-color: var(--primary-color);
  background-color: #eff6ff;
  box-shadow: 0 0 0 1px var(--primary-color);
}

.item-color-indicator {
  width: 14px;
  height: 14px;
  border-radius: 50%;
  flex-shrink: 0;
}

.item-info {
  display: flex;
  flex-direction: column;
  flex-grow: 1;
}

.item-name {
  font-size: 0.95rem;
  font-weight: 600;
  color: var(--text-main);
}

.item-percent {
  font-size: 0.8rem;
  color: var(--text-muted);
}

.item-amount {
  font-size: 1rem;
  font-weight: 700;
  color: var(--text-main);
  margin-right: 8px;
}

.item-delete-btn {
  background: none;
  border: none;
  color: var(--text-light);
  cursor: pointer;
  padding: 6px;
  border-radius: var(--radius-sm);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: all 0.2s ease;
}

.item-delete-btn:hover {
  color: var(--danger-color);
  background-color: #fee2e2;
}

/* 追加フォーム */
.add-form {
  background-color: var(--bg-card);
  border-radius: var(--radius-lg);
  padding: 20px;
  box-shadow: var(--shadow-sm);
  border: 1px solid var(--border-color);
  display: flex;
  flex-direction: column;
  gap: 12px;
}

.form-row {
  display: flex;
  gap: 10px;
  flex-wrap: wrap;
}

.form-input {
  flex: 1 1 140px;
  padding: 10px 14px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  font-size: 0.95rem;
  color: var(--text-main);
  background-color: #ffffff;
  outline: none;
  transition: border-color 0.2s, box-shadow 0.2s;
}

.form-input:focus {
  border-color: var(--primary-color);
  box-shadow: 0 0 0 3px rgba(59, 130, 246, 0.15);
}

.form-color-picker {
  width: 44px;
  height: 42px;
  padding: 2px;
  border: 1px solid var(--border-color);
  border-radius: var(--radius-sm);
  background-color: #ffffff;
  cursor: pointer;
}

.btn-add {
  padding: 10px 18px;
  background-color: var(--primary-color);
  color: #ffffff;
  border: none;
  border-radius: var(--radius-sm);
  font-size: 0.95rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s;
  white-space: nowrap;
}

.btn-add:hover {
  background-color: var(--primary-hover);
}

.btn-add:disabled {
  background-color: #94a3b8;
  cursor: not-allowed;
}

@media (max-width: 480px) {
  .app-container {
    padding: 16px 12px;
  }

  .chart-section {
    padding: 16px;
  }

  .chart-wrapper {
    height: 260px;
  }

  .form-row {
    flex-direction: column;
  }

  .btn-add {
    width: 100%;
  }
}

export interface ExpenseItem {
  id: string;
  name: string;
  amount: number;
  color: string;
}

export interface ExpenseChartProps {
  items: ExpenseItem[];
  selectedId: string | null;
  onSelect: (id: string | null) => void;
}

export interface ExpenseListProps {
  items: ExpenseItem[];
  selectedId: string | null;
  onSelect: (id: string | null) => void;
  onAdd: (item: Omit<ExpenseItem, 'id'>) => void;
  onDelete: (id: string) => void;
  totalAmount: number;
}

import { useMemo } from 'react';
import { PieChart, Pie, Cell, ResponsiveContainer, Tooltip, Sector } from 'recharts';
import { ExpenseChartProps, ExpenseItem } from '../types';

interface RenderActiveShapeProps {
  cx: number;
  cy: number;
  innerRadius: number;
  outerRadius: number;
  startAngle: number;
  endAngle: number;
  fill: string;
}

const renderActiveShape = (props: RenderActiveShapeProps) => {
  const { cx, cy, innerRadius, outerRadius, startAngle, endAngle, fill } = props;
  return (
    <g>
      <Sector
        cx={cx}
        cy={cy}
        innerRadius={innerRadius - 4}
        outerRadius={outerRadius + 8}
        startAngle={startAngle}
        endAngle={endAngle}
        fill={fill}
      />
    </g>
  );
};

export default function ExpenseChart({
  items = [],
  selectedId = null,
  onSelect,
}: ExpenseChartProps) {
  const totalAmount = useMemo(() => {
    return items.reduce((sum, item) => sum + item.amount, 0);
  }, [items]);

  const selectedItem = useMemo(() => {
    return items.find((item) => item.id === selectedId) || null;
  }, [items, selectedId]);

  const activeIndex = useMemo(() => {
    if (!selectedId) return -1;
    return items.findIndex((item) => item.id === selectedId);
  }, [items, selectedId]);

  const handlePieClick = (entry: ExpenseItem) => {
    if (selectedId === entry.id) {
      onSelect?.(null);
    } else {
      onSelect?.(entry.id);
    }
  };

  const centerLabel = selectedItem ? selectedItem.name : '合計支出';
  const centerAmount = selectedItem
    ? `¥${selectedItem.amount.toLocaleString()}`
    : `¥${totalAmount.toLocaleString()}`;

  return (
    <div className="chart-section">
      <div className="chart-wrapper">
        {items.length === 0 ? (
          <div className="selected-info-placeholder">
            データがありません。支出項目を追加してください。
          </div>
        ) : (
          <ResponsiveContainer width="100%" height="100%">
            <PieChart>
              <Tooltip
                formatter={(value: number) => [`¥${value.toLocaleString()}`, '金額']}
                contentStyle={{
                  backgroundColor: '#ffffff',
                  borderRadius: '8px',
                  border: '1px solid #e2e8f0',
                  boxShadow: '0 4px 6px -1px rgba(0, 0, 0, 0.1)',
                }}
              />
              <Pie
                data={items}
                dataKey="amount"
                nameKey="name"
                cx="50%"
                cy="50%"
                innerRadius={70}
                outerRadius={105}
                paddingAngle={3}
                activeIndex={activeIndex >= 0 ? activeIndex : undefined}
                activeShape={renderActiveShape}
                onClick={handlePieClick}
                cursor="pointer"
              >
                {items.map((entry) => (
                  <Cell
                    key={`cell-${entry.id}`}
                    fill={entry.color}
                    opacity={selectedId && selectedId !== entry.id ? 0.45 : 1}
                    style={{ transition: 'opacity 0.2s ease, transform 0.2s ease' }}
                  />
                ))}
              </Pie>
              <text
                x="50%"
                y="46%"
                className="chart-center-label"
                dominantBaseline="middle"
              >
                {centerLabel}
              </text>
              <text
                x="50%"
                y="55%"
                className="chart-center-amount"
                dominantBaseline="middle"
              >
                {centerAmount}
              </text>
            </PieChart>
          </ResponsiveContainer>
        )}
      </div>
    </div>
  );
}

import { useState, useMemo, ChangeEvent, FormEvent } from 'react';
import { Trash2 } from 'lucide-react';
import { ExpenseListProps, ExpenseItem } from '../types';

const DEFAULT_COLOR = '#3b82f6';

export default function ExpenseDetail({
  items = [],
  selectedId = null,
  onSelect,
  onAdd,
  onDelete,
  totalAmount = 0,
}: ExpenseListProps) {
  const [name, setName] = useState('');
  const [amount, setAmount] = useState('');
  const [color, setColor] = useState(DEFAULT_COLOR);

  const selectedItem = useMemo(() => {
    return items.find((item) => item.id === selectedId) || null;
  }, [items, selectedId]);

  const selectedPercent = useMemo(() => {
    if (!selectedItem || totalAmount === 0) return '0.0';
    return ((selectedItem.amount / totalAmount) * 100).toFixed(1);
  }, [selectedItem, totalAmount]);

  const handleSubmit = (e: FormEvent) => {
    e.preventDefault();
    const parsedAmount = parseInt(amount, 10);
    if (!name.trim() || isNaN(parsedAmount) || parsedAmount <= 0) {
      return;
    }

    onAdd?.({
      name: name.trim(),
      amount: parsedAmount,
      color,
    });

    setName('');
    setAmount('');
  };

  const handleItemClick = (id: string) => {
    if (selectedId === id) {
      onSelect?.(null);
    } else {
      onSelect?.(id);
    }
  };

  const handleDelete = (e: React.MouseEvent, id: string) => {
    e.stopPropagation();
    onDelete?.(id);
  };

  return (
    <div className="list-section">
      {/* 選択項目の詳細カード */}
      {selectedItem ? (
        <div className="selected-info-card">
          <div className="selected-info-title">{selectedItem.name} の内訳</div>
          <div className="selected-info-amount">
            ¥{selectedItem.amount.toLocaleString()}
          </div>
          <div className="selected-info-percent">
            全体比: {selectedPercent}%
          </div>
        </div>
      ) : (
        <div className="selected-info-card">
          <div className="selected-info-placeholder">
            グラフのセクターまたはリスト項目をクリックすると詳細が表示されます
          </div>
        </div>
      )}

      {/* 合計金額カード */}
      <div className="total-summary-card">
        <span className="total-label">今月の支出合計</span>
        <span className="total-value">¥{totalAmount.toLocaleString()}</span>
      </div>

      {/* 支出項目リスト */}
      <div className="item-list">
        {items.map((item: ExpenseItem) => {
          const isSelected = item.id === selectedId;
          const percent =
            totalAmount > 0
              ? ((item.amount / totalAmount) * 100).toFixed(1)
              : '0.0';

          return (
            <div
              key={item.id}
              className={isSelected ? 'item-card item-card-selected' : 'item-card'}
              onClick={() => handleItemClick(item.id)}
            >
              <div
                className="item-color-indicator"
                style={{ backgroundColor: item.color }}
              />
              <div className="item-info">
                <span className="item-name">{item.name}</span>
                <span className="item-percent">{percent}%</span>
              </div>
              <span className="item-amount">
                ¥{item.amount.toLocaleString()}
              </span>
              <button
                type="button"
                className="item-delete-btn"
                title={`${item.name}を削除`}
                onClick={(e) => handleDelete(e, item.id)}
              >
                <Trash2 size={16} />
              </button>
            </div>
          );
        })}
      </div>

      {/* 追加フォーム */}
      <form className="add-form" onSubmit={handleSubmit}>
        <div className="form-row">
          <input
            type="text"
            className="form-input"
            placeholder="項目名 (例: カフェ代)"
            value={name}
            onChange={(e: ChangeEvent<HTMLInputElement>) => setName(e.target.value)}
            required
          />
          <input
            type="number"
            className="form-input"
            placeholder="金額 (円)"
            min="1"
            value={amount}
            onChange={(e: ChangeEvent<HTMLInputElement>) => setAmount(e.target.value)}
            required
          />
          <input
            type="color"
            className="form-color-picker"
            title="項目の色"
            value={color}
            onChange={(e: ChangeEvent<HTMLInputElement>) => setColor(e.target.value)}
          />
          <button
            type="submit"
            className="btn-add"
            disabled={!name.trim() || !amount}
          >
            追加する
          </button>
        </div>
      </form>
    </div>
  );
}

import { useState, useMemo } from 'react';
import { ExpenseItem } from './types';
import ExpenseChart from './components/ExpenseChart';
import ExpenseDetail from './components/ExpenseDetail';
import './index.css';

const INITIAL_EXPENSES: ExpenseItem[] = [
  { id: '1', name: '食費', amount: 65000, color: '#f97316' },
  { id: '2', name: '住居費', amount: 88000, color: '#3b82f6' },
  { id: '3', name: '水道・光熱費', amount: 18500, color: '#06b6d4' },
  { id: '4', name: '通信費', amount: 12000, color: '#8b5cf6' },
  { id: '5', name: '日用品費', amount: 14500, color: '#10b981' },
  { id: '6', name: '交際・娯楽費', amount: 28000, color: '#ec4899' },
  { id: '7', name: '医療・保険費', amount: 16000, color: '#eab308' },
];

export default function App() {
  const [items, setItems] = useState<ExpenseItem[]>(INITIAL_EXPENSES);
  const [selectedId, setSelectedId] = useState<string | null>(null);

  const totalAmount = useMemo(() => {
    return items.reduce((sum, item) => sum + item.amount, 0);
  }, [items]);

  const handleSelect = (id: string | null) => {
    setSelectedId(id);
  };

  const handleAdd = (newItemData: Omit<ExpenseItem, 'id'>) => {
    const newItem: ExpenseItem = {
      ...newItemData,
      id: Date.now().toString(),
    };
    setItems((prev) => [...prev, newItem]);
    setSelectedId(newItem.id);
  };

  const handleDelete = (id: string) => {
    setItems((prev) => prev.filter((item) => item.id !== id));
    if (selectedId === id) {
      setSelectedId(null);
    }
  };

  return (
    <div className="app-container">
      <header className="header">
        <h1 className="header-title">家計支出内訳ダッシュボード</h1>
        <p className="header-subtitle">
          円グラフのセクターまたはリスト項目をクリックして支出の詳細・割合を確認できます
        </p>
      </header>

      <main className="main-layout">
        <ExpenseChart
          items={items}
          selectedId={selectedId}
          onSelect={handleSelect}
        />
        <ExpenseDetail
          items={items}
          selectedId={selectedId}
          onSelect={handleSelect}
          onAdd={handleAdd}
          onDelete={handleDelete}
          totalAmount={totalAmount}
        />
      </main>
    </div>
  );
}
